class Animal {
  constructor(name) {
    this.name = name;
  }
  speak() {
    return this.name + ' bersuara';
  }
}

class Dog extends Animal {
  constructor(name, breed) {
    Animal(name);
    this.breed = breed;
  }
  speak() {
    return super.speak() + ', guk!';
  }
}

