class Temperature {
  constructor(celsius) {
    this._c = celsius;
  }
  {{blank}} fahrenheit() {
    return this._c * 9 / 5 + 32;
  }
  {{blank}} fahrenheit(f) {
    this._c = (f - 32) * 5 / 9;
  }
}

function convert(celsius, newF) {
  const t = new Temperature(celsius);
  const before = t.fahrenheit;
  t.fahrenheit = newF;
  return [before, t._c];
}
